<?php
require_once __DIR__.'/../includes/functions.php';wajibRole('siswa');$uid=(int)currentUser()['id_user'];if($_SERVER['REQUEST_METHOD']==='POST'){csrfCheck();$lid=(int)$_POST['id_laporan'];$s=$koneksi->prepare('DELETE FROM bookmark WHERE id_user=? AND id_laporan=?');$s->bind_param('ii',$uid,$lid);$s->execute();flash('Bookmark dihapus.');redirect('siswa/bookmark.php');}$s=$koneksi->prepare('SELECT l.*,b.id_bookmark,k.nama_kategori,lo.nama_lokasi FROM bookmark b JOIN laporan l ON l.id_laporan=b.id_laporan JOIN kategori k ON k.id_kategori=l.id_kategori JOIN lokasi lo ON lo.id_lokasi=l.id_lokasi WHERE b.id_user=? ORDER BY b.created_at DESC');$s->bind_param('i',$uid);$s->execute();$rows=$s->get_result();$pageTitle='Bookmark';require __DIR__.'/../includes/header.php';?><div class="panel"><h2>Barang tersimpan</h2><?php if(!$rows->num_rows):?><div class="empty">Belum ada barang tersimpan.</div><?php endif;?><div class="table-wrap"><table><tr><th>Barang</th><th>Jenis</th><th>Lokasi</th><th>Aksi</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['nama_barang'])?></td><td><?=e($r['jenis_laporan'])?></td><td><?=e($r['nama_lokasi'])?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrfToken())?>"><input type="hidden" name="id_laporan" value="<?=$r['id_laporan']?>"><button class="btn danger sm">Hapus</button></form></td></tr><?php endwhile;?></table></div></div><?php require __DIR__.'/../includes/footer.php';?>
